# Try shifting diagonal indices by some amount
# Original diagonal indices present: -8, 0, 2, 7, 9, 11

def shifted_diag_grid(grid, shift):
    rows = len(grid)
    cols = len(grid[0])

    # Create value map from original grid's non-zero cells
    diag_to_value = {}
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] != 0:
                d = r - c
                diag_to_value[d] = grid[r][c]

    # Fill new grid with shifted assignments
    result = []
    for r in range(rows):
        row_vals = []
        for c in range(cols):
            orig_d = r - c - shift
            if orig_d in diag_to_value:
                row_vals.append(diag_to_value[orig_d])
            else:
                row_vals.append(0)
        result.append(row_vals)
    return result

